/* @lc app=leetcode id=3975 lang=kotlin */ class Solution { fun filterOccupiedIntervals(occupiedIntervals: Array<IntArray>, freeStart: Int, freeEnd: Int): List<List<Int>> = occupiedIntervals.sortedBy { it[0] }.fold(ArrayList<IntArray>()) { acc, iv -> acc.also { if (it.isNotEmpty() && iv[0] <= it.last()[1] + 1) it.last().set(1, maxOf(it.last()[1], iv[1])) else it.add(intArrayOf(iv[0], iv[1])) } }.flatMap { (a, b) -> listOf(a to minOf(b, freeStart - 1), maxOf(a, freeEnd + 1) to b).filter { it.first <= it.second }.map { listOf(it.first, it.second) } } }